"""Spectre state files (docs/VAMOS_SPECTRE_DESIGN.md §8.6 [M UG pp.203-204]; the API is the §10 block).

Written by `write=`/`writefinal=` from the full-solution saves (§5.4), read by `readns`, `readic`
and `read=`:

    # State file generated by Spectre from circuit file 'opamp.scs'
    # during 'stepresponse' at 5:39:38 PM, jan 21, 1992.
    out 1.17406247989272
    I2.Mid 0.588793510612534
    V1:p -0.001

Nets first (hierarchical with `.`), then the vsource currents (`V1:p`); 15 significant digits
(%.15g), keeping the leading zero the UG's example drops (§14 q.49).  `state_date(t)` gives the
header's date: §8.2's time, no day name, the month in lower case, the day unpadded.

Reading: `#` starts a comment; an entry whose name carries `:` is a current entry (`V1:p`), any
other a node entry.  The caller drops the current entries with one note (`readns`) or one warning
(`readic`): "<n> current entries not applied" (§8.6).

Names are Spectre's (a<0>, b.c, X.1.m.n).  A character the line format would read otherwise is
written with a backslash before it, as a netlist escapes it (UG p.60): a blank or another white-space
character, `#`, `\\`, and the `:` of a node name (a current entry's last `:` is its terminal
separator), so the node `a b` is `a\\ b` and the node `a:b` is `a\\:b`; the reader takes a backslash
as escaping the next character, so a file a user writes with netlist spellings (`net\\<0\\>`) reads
too (the phase-2e escaped names: a name with a blank was an unreadable line).

The files are UTF-8, as the PSF files are (§14 q.62, decided 2026-10-23; names.FILE_ENCODING): every name and
the circuit file's name are written as they are (round 4 wrote Latin-1, a name it could not hold in its escaped
form and the circuit's name with `?`; FIX2E4: before that, two such names were two entries `?', and the file
could not be read back: `readic ?: wildcards are not supported').  A file is read as UTF-8, and as Latin-1 when
its bytes are not UTF-8: a file written by hand in Latin-1 (`né 0.5`) reads as the name it spells.
"""

from __future__ import annotations

import os
from datetime import datetime
from typing import Dict, List, Mapping, Optional, Tuple

from vamos.names import FILE_ENCODING, FILE_ERRORS
from vamos.notes import Note

_MONTHS = ("jan", "feb", "mar", "apr", "may", "jun", "jul", "aug", "sep", "oct", "nov", "dec")
VALUE_FORMAT = "%.15g"
_ESCAPED = "#\\:"                  # besides white space: the comment, the escape, the terminal separator


def name_text(name: str, current: bool = False) -> str:
    """A name as a state-file line spells it (the module docstring); current: a current entry `<path>:<terminal>`,
    whose last `:` stays the separator."""
    if current and ":" in name:
        path, _, term = name.rpartition(":")
        return name_text(path) + ":" + name_text(term)
    return "".join("\\" + c if (c.isspace() or c in _ESCAPED) else c for c in name)


def _split_name(text: str) -> Tuple[str, str, bool]:
    """(the name, the rest of the line, whether the name holds an unescaped `:`): the name runs to the first unescaped
    white space, a backslash escaping the next character."""
    out: List[str] = []
    colon = False
    i = 0
    while i < len(text):
        c = text[i]
        if c == "\\" and i + 1 < len(text):
            out.append(text[i + 1])
            i += 2
            continue
        if c.isspace():
            break
        if c == ":":
            colon = True
        out.append(c)
        i += 1
    return "".join(out), text[i:].strip(), colon


def _comment_free(raw: str) -> str:
    """The line before its first unescaped `#`."""
    i = 0
    while i < len(raw):
        if raw[i] == "\\":
            i += 2
            continue
        if raw[i] == "#":
            return raw[:i]
        i += 1
    return raw


def state_date(t: datetime) -> str:
    """The header's date: `5:39:38 PM, jan 21, 1992` [M UG p.204] (the time as §8.2's, no day name,
    the month in lower case, the day unpadded)."""
    hour = t.hour % 12 or 12
    return "%d:%02d:%02d %s, %s %d, %d" % (hour, t.minute, t.second, "AM" if t.hour < 12 else "PM",
                                          _MONTHS[t.month - 1], t.day, t.year)


def write(path: str, nodes: Mapping[str, float], currents: Mapping[str, float], circuit: str,
          analysis: str, date: str, notes: Optional[List[Note]] = None) -> None:
    """Write a state file (§8.6): the two-line `#` header, then `<name> <value>` per entry, the
    nodes in the given order, then the currents.  UTF-8, as the PSF files are (the module docstring):
    every name and the netlist's file name as they are; only a lone surrogate is written otherwise
    (names.FILE_ERRORS; the guide trial of phase 2e, TRIAL2E2-F2: an Omega in the netlist's file name
    was an internal error).  `notes` is the writers' common parameter: nothing is noted here, since no
    name is written otherwise than it is (round 4 noted the names Latin-1 could not hold)."""
    tmp = path + ".vamos-tmp"
    with open(tmp, "w", encoding=FILE_ENCODING, errors=FILE_ERRORS, newline="\n") as fh:
        fh.write("# State file generated by Spectre from circuit file '%s'\n" % circuit)
        fh.write("# during '%s' at %s.\n" % (analysis, date))
        for table, current in ((nodes, False), (currents, True)):
            for n, value in table.items():
                fh.write("%s %s\n" % (name_text(n, current), VALUE_FORMAT % float(value)))
    os.replace(tmp, path)


def read_text(path: str) -> str:
    """A state file's text: UTF-8, or Latin-1 for a file whose bytes are not UTF-8 (one written by hand in a Latin-1
    editor; the module docstring)."""
    with open(path, "rb") as fh:
        data = fh.read()
    try:
        return data.decode(FILE_ENCODING)
    except UnicodeDecodeError:
        return data.decode("latin-1")


def read(path: str) -> Tuple[Dict[str, float], Dict[str, float]]:
    """Read a state file: (node entries, current entries), in file order, by their names (a backslash
    escapes the next character, the module docstring); `#` starts a comment.  A line that is not
    `<name> <number>` is a ValueError naming the file and line."""
    nodes: Dict[str, float] = {}
    currents: Dict[str, float] = {}
    for lineno, raw in enumerate(read_text(path).splitlines(), 1):
        text = _comment_free(raw).strip()
        if not text:
            continue
        name, value, current = _split_name(text)
        if not name or not value or len(value.split()) != 1:
            raise ValueError("%s:%d: expected `<name> <value>`, got %r" % (path, lineno, raw))
        try:
            v = float(value)
        except ValueError:
            raise ValueError("%s:%d: %r is not a number" % (path, lineno, value))
        (currents if current else nodes)[name] = v
    return nodes, currents


__all__ = ["write", "read", "read_text", "state_date", "name_text", "VALUE_FORMAT"]
